INSERT INTO `wp_postmeta` VALUES (3048,925,'introduction','<img class=\"alignnone size-medium wp-image-832\" src=\"https://flightsholboxv1.local/wp-content/uploads/2026/07/cancun-letters-225x300.webp\" alt=\"Cancun Letters\" width=\"225\" height=\"300\" /><img class=\"alignnone size-medium wp-image-795\" src=\"https://flightsholboxv1.local/wp-content/uploads/2026/07/cancun-private-terminal-entrance-300x214.webp\" alt=\"Cancun private terminal entrance\" width=\"300\" height=\"214\" /><img class=\"alignnone size-medium wp-image-794\" src=\"https://flightsholboxv1.local/wp-content/uploads/2026/07/cancun-airport-map-300x200.webp\" alt=\"Cancun airport map with location of private terminal FBO\" width=\"300\" height=\"200\" /><img class=\"alignnone size-medium wp-image-796\" src=\"https://flightsholboxv1.local/wp-content/uploads/2026/07/cancun-private-terminal-fbo-250x300.webp\" alt=\"Cancun private terminal FBO check in\" width=\"250\" height=\"300\" /><img class=\"alignnone size-medium wp-image-751\" src=\"https://flightsholboxv1.local/wp-content/uploads/2026/07/private-airport-cancun-fbo-runway-300x200.webp\" alt=\"private airport Cancun FBO with yet on runway\" width=\"300\" height=\"200\" />\r\n\r\n<strong><span style=\"color: #f50c0c;\">maybe those images</span> <span style=\"color: #f50c0c;\">can be in a slider all the way down at the end of the page. + button that links back to Home page</span></strong>\r\n\r\n&nbsp;');
