INSERT INTO `wp_posts` VALUES (1,1,'2026-06-12 21:00:14','2026-06-12 20:00:14','<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->','Hello world!','','publish','open','open','','hello-world','','','2026-06-12 21:00:14','2026-06-12 20:00:14','',0,'http://flightsholboxv1.local/?p=1',0,'post','',1);
INSERT INTO `wp_posts` VALUES (2,1,'2026-06-12 21:00:14','2026-06-12 20:00:14','<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like piña coladas. (And gettin\' caught in the rain.)</p></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to your dashboard to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Sample Page','','trash','closed','open','','sample-page__trashed','','','2026-07-04 09:59:16','2026-07-04 08:59:16','',0,'http://flightsholboxv1.local/?page_id=2',0,'page','',0);
INSERT INTO `wp_posts` VALUES (4,0,'2026-06-12 21:09:45','2026-06-12 20:09:45','<!-- wp:page-list /-->','Navigation','','publish','closed','closed','','navigation','','','2026-06-12 21:09:45','2026-06-12 20:09:45','',0,'http://flightsholboxv1.local/navigation/',0,'wp_navigation','',0);
