INSERT INTO `wp_posts` VALUES (339,1,'2026-07-08 18:38:39','2026-07-08 17:38:39','<!-- wp:acf/hero-panel {\"name\":\"acf/hero-panel\",\"data\":{\"hero_slides_0_slide_image\":84,\"_hero_slides_0_slide_image\":\"field_6a465a86ac589\",\"hero_slides_1_slide_image\":85,\"_hero_slides_1_slide_image\":\"field_6a465a86ac589\",\"hero_slides_2_slide_image\":86,\"_hero_slides_2_slide_image\":\"field_6a465a86ac589\",\"hero_slides\":3,\"_hero_slides\":\"field_6a465a79ac588\",\"hero_heading\":\"Example Heading\",\"_hero_heading\":\"field_6a465aa9ac58a\",\"hero_intro\":\"Example Intro\",\"_hero_intro\":\"field_6a465ab2ac58b\"},\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/text-panel {\"name\":\"acf/text-panel\",\"data\":{\"content\":\"\\u003ch2 class=\\u0022section-heading small-bot\\u0022 style=\\u0022text-align: center;\\u0022\\u003e\\u003cspan style=\\u0022color: #e6af2a;\\u0022\\u003ePrivate Flights Cancun to Holbox- Book Your Air Taxi\\u003c/span\\u003e\\u003c/h2\\u003e\\r\\n\\u003cdiv class=\\u0022section-intro \\u0022\\u003e\\r\\n\\u003ch4 class=\\u0022tiny-bot\\u0022 style=\\u0022text-align: center;\\u0022\\u003ePrivate Air Taxi from Cancún to Holbox, Cozumel, Playa del Carmen, Merida and many more destinations.\\u003c/h4\\u003e\\r\\nWe pride ourselves on being professional and efficient. Flights-Holbox is one of the few operators in the Riviera Maya offering a fully licensed private air taxi service with more than 17 years of experience. Whether you need a private air taxi from Cancun to Holbox or flights to Cozumel, Merida or Playa del Carmen, we have you covered.\\r\\n\\r\\nWe will make sure you get the best service possible because the last thing you need is stressing about your transfer. It\'s so important to choose a professional, experienced and safe operator.\\r\\n\\r\\n\\u003c/div\\u003e\",\"_content\":\"field_6a465ad18514f\",\"text_alignment\":\"center\",\"_text_alignment\":\"field_6a47a299896e2\",\"background_colour\":\"navy\",\"_background_colour\":\"field_69fb291d7099f\",\"container_size\":\"medium\",\"_container_size\":\"field_6a104fa067637\",\"panel_settings\":\"\",\"_panel_settings\":\"field_6a47a682138e0\"},\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/slider-panel {\"name\":\"acf/slider-panel\",\"data\":{\"slider_heading\":\"\",\"_slider_heading\":\"field_6a47ba31b36fd\",\"slider_intro\":\"\",\"_slider_intro\":\"field_6a47ba60b36fe\",\"slider_items_0_slide_post\":134,\"_slider_items_0_slide_post\":\"field_6a47ba81b3700\",\"slider_items_0_button_button_link\":\"\",\"_slider_items_0_button_button_link\":\"field_6a10337e94d01\",\"slider_items_0_button_button_colour\":\"white\",\"_slider_items_0_button_button_colour\":\"field_69fb154a3681d\",\"slider_items_0_button\":\"\",\"_slider_items_0_button\":\"field_6a47bb3fb3701\",\"slider_items_1_slide_post\":220,\"_slider_items_1_slide_post\":\"field_6a47ba81b3700\",\"slider_items_1_button_button_link\":\"\",\"_slider_items_1_button_button_link\":\"field_6a10337e94d01\",\"slider_items_1_button_button_colour\":\"white\",\"_slider_items_1_button_button_colour\":\"field_69fb154a3681d\",\"slider_items_1_button\":\"\",\"_slider_items_1_button\":\"field_6a47bb3fb3701\",\"slider_items\":2,\"_slider_items\":\"field_6a47ba6db36ff\",\"background_colour\":\"\",\"_background_colour\":\"field_69fb291d7099f\",\"container_size\":\"\",\"_container_size\":\"field_6a104fa067637\",\"panel_settings\":\"\",\"_panel_settings\":\"field_6a47bb6507269\"},\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/text-column-panel {\"name\":\"acf/text-column-panel\",\"data\":{\"heading\":\"\",\"_heading\":\"field_6a48c9e16d855\",\"columns_0_column_content\":\"We pride ourselves on being professional and efficient. Flights-Holbox is one of the few operators in the Riviera Maya offering a fully licensed private air taxi service with more than 17 years of experience. Whether you need a private air taxi from Cancun to Holbox or flights to Cozumel, Merida or Playa del Carmen, we have you covered.\",\"_columns_0_column_content\":\"field_6a48ca046d857\",\"columns_1_column_content\":\"\",\"_columns_1_column_content\":\"field_6a48ca046d857\",\"columns\":2,\"_columns\":\"field_6a48c9ed6d856\"},\"mode\":\"edit\"} /-->','Example Page 2','','inherit','closed','closed','','332-revision-v1','','','2026-07-08 18:38:39','2026-07-08 17:38:39','',332,'http://flightsholboxv1.local/?p=339',0,'revision','',0);
