INSERT INTO `wp_posts` VALUES (976,2,'2026-07-24 17:56:34','2026-07-24 16:56:34','<!-- wp:acf/hero-panel {\"name\":\"acf/hero-panel\",\"data\":{\"hero_slides_0_slide_image\":754,\"_hero_slides_0_slide_image\":\"field_6a465a86ac589\",\"hero_slides_1_slide_image\":974,\"_hero_slides_1_slide_image\":\"field_6a465a86ac589\",\"hero_slides_2_slide_image\":740,\"_hero_slides_2_slide_image\":\"field_6a465a86ac589\",\"hero_slides_3_slide_image\":749,\"_hero_slides_3_slide_image\":\"field_6a465a86ac589\",\"hero_slides\":4,\"_hero_slides\":\"field_6a465a79ac588\",\"hero_heading\":\"About Flights Holbox\",\"_hero_heading\":\"field_6a465aa9ac58a\",\"hero_intro\":\"\",\"_hero_intro\":\"field_6a465ab2ac58b\"},\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/two-column-panel {\"name\":\"acf/two-column-panel\",\"data\":{\"heading\":\"Flights Holbox- Providing safe, licensed private flights between Cancun and Holbox for more than 17 years.\",\"_heading\":\"field_6a47e23efca24\",\"intro\":\"\",\"_intro\":\"field_6a47e24dfca25\",\"column_one\":\"\\u003ch4 data-section-id=\\u0022641xdp\\u0022 data-start=\\u00221033\\u0022 data-end=\\u00221056\\u0022\\u003e\\u003c/h4\\u003e\\r\\n\\u003ch4 data-section-id=\\u0022641xdp\\u0022 data-start=\\u00221033\\u0022 data-end=\\u00221056\\u0022\\u003e\\u003c/h4\\u003e\\r\\n\\u003ch4 class=\\u0022PDq2pG_selectionAnchorContainer\\u0022 style=\\u0022text-align: center;\\u0022 data-section-id=\\u0022641xdp\\u0022 data-start=\\u00221033\\u0022 data-end=\\u00221056\\u0022\\u003e\\u003cspan style=\\u0022color: #00467b;\\u0022\\u003eWhy choose Flights Holbox\\u003c/span\\u003e\\u003c/h4\\u003e\\r\\n\\u0026nbsp;\\r\\n\\u003cp data-start=\\u00221058\\u0022 data-end=\\u00221193\\u0022\\u003eFlights Holbox has been providing private air transfers and ground transportation between Cancun and Holbox for more than\\u003cspan style=\\u0022color: #00467b;\\u0022\\u003e \\u003cstrong data-start=\\u00221180\\u0022 data-end=\\u00221192\\u0022\\u003e17 years\\u003c/strong\\u003e.\\u003c/span\\u003e\\u003c/p\\u003e\\r\\n\\u003cp data-start=\\u00221058\\u0022 data-end=\\u00221193\\u0022\\u003e\\u003c/p\\u003e\\r\\n\\u003cp data-start=\\u00221195\\u0022 data-end=\\u00221227\\u0022\\u003eOur goal has always been simple:\\u003c/p\\u003e\\r\\n\\u003cp data-start=\\u00221229\\u0022 data-end=\\u00221297\\u0022\\u003e\\u003cstrong data-start=\\u00221229\\u0022 data-end=\\u00221297\\u0022\\u003e\\u003cspan style=\\u0022color: #00467b;\\u0022\\u003eWe offer the fastest, safest and most reliable way to reach Holbox\\u003c/span\\u003e.\\u003c/strong\\u003e\\u003c/p\\u003e\\r\\n\\u003cp data-start=\\u00221299\\u0022 data-end=\\u00221433\\u0022\\u003eWhether you travel for vacation, business or a special occasion, our experienced team makes every journey smooth from start to finish.\\u003c/p\\u003e\",\"_column_one\":\"field_6a47e256fca26\",\"column_two\":\"\\u003ch4 data-section-id=\\u0022641xdp\\u0022 data-start=\\u00221033\\u0022 data-end=\\u00221056\\u0022\\u003e\\u003c/h4\\u003e\\r\\n\\u003ch4 data-section-id=\\u0022641xdp\\u0022 data-start=\\u00221033\\u0022 data-end=\\u00221056\\u0022\\u003e\\u003c/h4\\u003e\\r\\n\\u003ch4 class=\\u0022PDq2pG_selectionAnchorContainer\\u0022 style=\\u0022text-align: center;\\u0022 data-section-id=\\u0022641xdp\\u0022 data-start=\\u00221033\\u0022 data-end=\\u00221056\\u0022\\u003e\\u003cspan style=\\u0022color: #00467b;\\u0022\\u003eGeneral Information\\u003c/span\\u003e\\u003c/h4\\u003e\\r\\n\\u0026nbsp;\\r\\n\\r\\nFlights operate between 7:00 AM and 5:30 PM and may vary depending on daylight and weather conditions.\\r\\n\\r\\nAll flights depart from the \\u003ca href=\\u0022https://share.google/RJ7qNegyN4t8bNdxD\\u0022\\u003eFBO (Fixed Base Operator)\\u003c/a\\u003e at Cancún International Airport.\\r\\n\\r\\nThe FBO can only be reached by taxi. We can arrange a private taxi for USD 30.\\r\\n\\r\\nPassengers departing from Cancún Airport must pay an airport tax of MXN 200 (USD 10), unless arriving and departing on the same day.\\r\\n\\r\\nWe accept cash, credit/debit cards, and PayPal.\",\"_column_two\":\"field_6a47e26dfca28\",\"pullout_summary\":\"With Flights Holbox you choose a professional company you can rely on, with a well-priced service. We will take you safely and comfortably to your final destination.\",\"_pullout_summary\":\"field_6a47e277fca29\"},\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/text-column-panel {\"name\":\"acf/text-column-panel\",\"data\":{\"heading\":\"Why choose Flights Holbox\",\"_heading\":\"field_6a48c9e16d855\",\"columns_0_column_content\":\"\\u003cp class=\\u0022PDq2pG_selectionAnchorContainer\\u0022 style=\\u0022text-align: center;\\u0022 data-start=\\u00221677\\u0022 data-end=\\u00221699\\u0022\\u003e✓ 17+ Years Experience\\u003c/p\\u003e\\r\\n\\u003cp style=\\u0022text-align: center;\\u0022 data-start=\\u00221728\\u0022 data-end=\\u00221749\\u0022\\u003e✓ Professional Pilots\\u003c/p\\u003e\\r\\n\\u003cp style=\\u0022text-align: center;\\u0022 data-start=\\u00221751\\u0022 data-end=\\u00221768\\u0022\\u003e✓ Private Flights\\u003c/p\\u003e\\r\\n\\u003cp style=\\u0022text-align: center;\\u0022 data-start=\\u00221770\\u0022 data-end=\\u00221798\\u0022\\u003e✓ Ground Transfers Available\\u003c/p\\u003e\\r\\n\\u003cp style=\\u0022text-align: center;\\u0022 data-start=\\u00221800\\u0022 data-end=\\u00221829\\u0022\\u003e✓ Hundreds of Happy Customers\\u003c/p\\u003e\\r\\n\\u003cp style=\\u0022text-align: center;\\u0022 data-start=\\u00221831\\u0022 data-end=\\u00221854\\u0022\\u003e✓ Fastest Way to Holbox\\u003c/p\\u003e\",\"_columns_0_column_content\":\"field_6a48ca046d857\",\"columns_1_column_content\":\"\\u003cp style=\\u0022text-align: center;\\u0022 data-start=\\u00221701\\u0022 data-end=\\u00221726\\u0022\\u003e✓ 30-Minute Flights to Most Destinations\\u003c/p\\u003e\\r\\n\\u003cp style=\\u0022text-align: center;\\u0022 data-start=\\u00221728\\u0022 data-end=\\u00221749\\u0022\\u003e✓ Fully Licensed Commercial Operator\\u003c/p\\u003e\\r\\n\\u003c