INSERT INTO `wp_posts` VALUES (1158,1,'2026-08-01 12:43:43','2026-08-01 11:43:43','<!-- wp:acf/hero-panel {\"name\":\"acf/hero-panel\",\"data\":{\"hero_slides_0_slide_image\":975,\"_hero_slides_0_slide_image\":\"field_6a465a86ac589\",\"hero_slides_1_slide_image\":750,\"_hero_slides_1_slide_image\":\"field_6a465a86ac589\",\"hero_slides_2_slide_image\":84,\"_hero_slides_2_slide_image\":\"field_6a465a86ac589\",\"hero_slides\":3,\"_hero_slides\":\"field_6a465a79ac588\",\"hero_heading\":\"Private Flights Riviera Maya\",\"_hero_heading\":\"field_6a465aa9ac58a\",\"hero_intro\":\"The fastest and most scenic way to reach your destination.\",\"_hero_intro\":\"field_6a465ab2ac58b\"},\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/booking-panel {\"name\":\"acf/booking-panel\",\"data\":{\"sister_site_url\":\"\",\"_sister_site_url\":\"field_6a465a2f24a91\",\"sister_site_label\":\"\",\"_sister_site_label\":\"field_6a465a4a24a92\"},\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/html-panel {\"name\":\"acf/html-panel\",\"data\":{\"html\":\"\\u003cstyle\\u003e\\r\\n  .fh-private-flight-intro {\\r\\n    max-width: 1100px;\\r\\n    margin: 60px auto;\\r\\n    padding: 0 24px;\\r\\n    box-sizing: border-box;\\r\\n    font-family: inherit;\\r\\n  }\\r\\n\\r\\n  .fh-intro-heading {\\r\\n    max-width: 760px;\\r\\n    margin: 0 auto 38px;\\r\\n    text-align: center;\\r\\n  }\\r\\n\\r\\n  .fh-intro-label {\\r\\n    margin: 0 0 10px;\\r\\n    color: #124f7c;\\r\\n    font-size: 14px;\\r\\n    font-weight: 600;\\r\\n    letter-spacing: 2px;\\r\\n    text-transform: uppercase;\\r\\n  }\\r\\n\\r\\n  .fh-intro-heading h2 {\\r\\n    margin: 0 0 16px;\\r\\n    color: #173d5b;\\r\\n    font-size: 36px;\\r\\n    font-weight: 400;\\r\\n    line-height: 1.25;\\r\\n  }\\r\\n\\r\\n  .fh-intro-heading p {\\r\\n    margin: 0;\\r\\n    color: #65727d;\\r\\n    font-size: 17px;\\r\\n    line-height: 1.75;\\r\\n  }\\r\\n\\r\\n  .fh-main-card {\\r\\n    position: relative;\\r\\n    margin-bottom: 24px;\\r\\n    padding: 48px 50px;\\r\\n    background:\\r\\n      linear-gradient(\\r\\n        135deg,\\r\\n        rgba(238, 247, 253, 0.95),\\r\\n        rgba(255, 255, 255, 0.98)\\r\\n      );\\r\\n    border: 1px solid #dce9f2;\\r\\n    border-radius: 20px;\\r\\n    box-shadow: 0 14px 40px rgba(18, 79, 124, 0.08);\\r\\n    overflow: hidden;\\r\\n  }\\r\\n\\r\\n  .fh-main-card::before {\\r\\n    content: \\u0022\\u0022;\\r\\n    position: absolute;\\r\\n    top: 0;\\r\\n    left: 0;\\r\\n    width: 6px;\\r\\n    height: 100%;\\r\\n    background: linear-gradient(180deg, #124f7c, #6dc5ff);\\r\\n  }\\r\\n\\r\\n  .fh-main-card h3 {\\r\\n    margin: 0 0 18px;\\r\\n    color: #124f7c;\\r\\n    font-size: 27px;\\r\\n    font-weight: 500;\\r\\n    line-height: 1.35;\\r\\n  }\\r\\n\\r\\n  .fh-main-card p {\\r\\n    margin: 0 0 17px;\\r\\n    color: #53626e;\\r\\n    font-size: 16px;\\r\\n    line-height: 1.8;\\r\\n  }\\r\\n\\r\\n  .fh-main-card p:last-child {\\r\\n    margin-bottom: 0;\\r\\n  }\\r\\n\\r\\n  .fh-card-grid {\\r\\n    display: grid;\\r\\n    grid-template-columns: repeat(2, minmax(0, 1fr));\\r\\n    gap: 24px;\\r\\n  }\\r\\n\\r\\n  .fh-info-card {\\r\\n    padding: 36px 34px;\\r\\n    background: #ffffff;\\r\\n    border: 1px solid #e1ebf2;\\r\\n    border-radius: 18px;\\r\\n    box-shadow: 0 10px 30px rgba(18, 79, 124, 0.07);\\r\\n    transition: transform 0.25s ease, box-shadow 0.25s ease;\\r\\n  }\\r\\n\\r\\n  .fh-info-card:hover {\\r\\n    transform: translateY(-4px);\\r\\n    box-shadow: 0 16px 36px rgba(18, 79, 124, 0.11);\\r\\n  }\\r\\n\\r\\n  .fh-icon {\\r\\n    width: 54px;\\r\\n    height: 54px;\\r\\n    margin-bottom: 20px;\\r\\n    border-radius: 50%;\\r\\n    background: #eef7fd;\\r\\n    color: #124f7c;\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    justify-content: center;\\r\\n    font-size: 25px;\\r\\n    line-height: 1;\\r\\n  }\\r\\n\\r\\n  .fh-info-card h3 {\\r\\n    margin: 0 0 15px;\\r\\n    color: #124f7c;\\r\\n    font-size: 23px;\\r\\n    font-weight: 500;\\r\\n    line-height: 1.35;\\r\\n  }\\r\\n\\r\\n  .fh-info-card p {\\r\\n    margin: 0;\\r\\n    color: #596873;\\r\\n    font-size: 16px;\\r\\n    line-height: 1.8;\\r\\n  }\\r\\n\\r\\n  .fh-intro-links {\\r\\n    margin-top: 28px;\\r\\n    padding: 26px 30px;\\r\\n    background: #124f7c;\\r\\n    border-radius: 16px;\\r\\n    text-align: center;\\r\\n  }\\r\\n\\r\\n  .fh-intro-links p {\\r\\n    margin: 0;\\r\\n    color: #ffffff;\\r\\n    font-size: 16px;\\r\\n    line-height: 1.7;\\r\\n  }\\r\\n\\r\\n  .fh-intro-links a {\\r\\n    color: #ffffff;\\r\\n    font-weight: 600;\\r\\n    text-decoration: underline;\\r\\n    text-underline-offset: 4px;\\r\\n  }\\r\\n\\r\\n  @media (max-width: 768px) {\\r\\n    .fh-private-flight-intro {\\r\\n      margin: 42px auto;\\r\\n      padding: 0 16px;\\r\\n    }\\r\\n\\r\\n    .fh-intro-heading h2 {\\r\\n      font-size: 29px;\\r\\n    }\\r\\n\\r\\n    .fh-main-card {\\r\\n      padding: 36px 28px 36px 32px;\\r\\n    }\\r\\n\\r\\n    .fh-card-grid {\\r\\n      grid-template-columns: 1fr;\\r\\n    }\\r\\n\\r\\n    .fh-info-card {\\r\\n      padding: 30px 26px;\\r\\n    }\\r\\n  }\\r\\n\\u003c/style\\u003e\\r\\n\\r\\n\\u003csection class=\\u0022fh-private-flight-intro\\u0022\\u003e\\r\\n\\r\\n  \\u003c!\\u002d\\u002d SECTION HEADING \\u002d\\u002d\\u003e\\r\\n  \\u003cdiv class=\\u0022fh-intro-heading\\u0022\\u003e\\r\\n\\r\\n    \\u003cp class=\\u0022fh-intro-label\\u0022\\u003e\\r\\n      Flights Holbox\\r\\n    \\u003c/p\\u003e\\r\\n\\r\\n    \\u003ch2\\u003e\\r\\n      Private Flights Across the Riviera Maya\\r\\n    \\u003c/h2\\u003e\\r\\n\\r\\n    \\u003cp\\u003e\\r\\n      Travel faster, enjoy complete privacy and experience Mexico’s Caribbean\\r\\n      coastline from an unforgettable perspective.\\r\\n    \\u003c/p\\u003e\\r\\n\\r\\n  \\u003c/div\\u003e\\r\\n\\r\\n\\r\\n  \\u003c!\\u002d\\u002d MAIN INTRODUCTION CARD \\u002d\\u002d\\u003e\\r\\n  \\u003cdiv class=\\u0022fh-main-card\\u0022\\u003e\\r\\n\\r\\n    \\u003ch3\\u003e\\r\\n      The Fastest Way to Reach Holbox and Beyond\\r\\n    \\u003c/h3\\u003e\\r\\n\\r\\n    \\u003cp\\u003e\\r\\n      \\u003cstrong\\u003ePrivate Flights to Holbox\\u003c/strong\\u003e offer one of the fastest,\\r\\n      most comfortable and most scenic ways to travel across the Riviera Maya.\\r\\n      Skip long drives, crowded ferries and unnecessary waiting times.\\r\\n    \\u003c/p\\u003e\\r\\n\\r\\n    \\u003cp\\u003e\\r\\n      Instead, fly directly to your destination while enjoying spectacular\\r\\n      aerial views of Mexico’s Caribbean coastline.\\r\\n    \\u003c/p\\u003e\\r\\n\\r\\n    \\u003cp\\u003e\\r\\n      Flights Holbox connects Holbox with Cancun, Playa del Carmen, Cozumel\\r\\n      and other regional destinations. We can also arrange custom routes,\\r\\n      depending on aircraft and airport availability.\\r\\n    \\u003c/p\\u003e\\r\\n\\r\\n  \\u003c/div\\u003e\\r\\n\\r\\n\\r\\n  \\u003c!\\u002d\\u002d TWO SUPPORTING CARDS \\u002d\\u002d\\u003e\\r\\n  \\u003cdiv class=\\u0022fh-card-grid\\u0022\\u003e\\r\\n\\r\\n    \\u003c!\\u002d\\u002d CARD 1 \\u002d\\u002d\\u003e\\r\\n    \\u003cdiv class=\\u0022fh-info-card\\u0022\\u003e\\r\\n\\r\\n      \\u003cdiv class=\\u0022fh-icon\\u0022 aria-hidden=\\u0022true\\u0022\\u003e\\r\\n        ✈\\r\\n      \\u003c/div\\u003e\\r\\n\\r\\n      \\u003ch3\\u003e\\r\\n        Travel on Your Schedule\\r\\n      \\u003c/h3\\u003e\\r\\n\\r\\n      \\u003cp\\u003e\\r\\n        Travel privately with your partner, family, friends or colleagues.\\r\\n        Our charter service gives you greater flexibility and helps you save\\r\\n        valuable vacation time.\\r\\n      \\u003c/p\\u003e\\r\\n\\r\\n    \\u003c/div\\u003e\\r\\n\\r\\n\\r\\n    \\u003c!\\u002d\\u002d CARD 2 \\u002d\\u002d\\u003e\\r\\n    \\u003cdiv class=\\u0022fh-info-card\\u0022\\u003e\\r\\n\\r\\n      \\u003cdiv class=\\u0022fh-icon\\u0022 aria-hidden=\\u0022true\\u0022\\u003e\\r\\n        ✓\\r\\n      \\u003c/div\\u003e\\r\\n\\r\\n      \\u003ch3\\u003e\\r\\n        Safety, Comfort and Experience\\r\\n      \\u003c/h3\\u003e\\r\\n\\r\\n      \\u003cp\\u003e\\r\\n        Experienced commercial pilots operate professionally maintained\\r\\n        aircraft and prioritize your comfort and safety throughout the\\r\\n        journey.\\r\\n      \\u003c/p\\u003e\\r\\n\\r\\n    \\u003c/div\\u003e\\r\\n\\r\\n  \\u003c/div\\u003e\\r\\n\\r\\n\\r\\n \",\"_html\":\"field_6a47b04e4ef49\"},\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/html-panel {\"name\":\"acf/html-panel\",\"data\":{\"html\":\"\\u003cstyle\\u003e\\r\\n.fh-process {\\r\\n    max-width: 1150px;\\r\\n    margin: 80px auto;\\r\\n    padding: 0 20px;\\r\\n    text-align: center;\\r\\n    box-sizing: border-box;\\r\\n}\\r\\n\\r\\n.fh-process-heading {\\r\\n    max-width: 780px;\\r\\n    margin: 0 auto 50px;\\r\\n}\\r\\n\\r\\n.fh-process-label {\\r\\n    margin: 0 0 10px;\\r\\n    color: #124f7c;\\r\\n    font-size: 14px;\\r\\n    font-weight: 600;\\r\\n    letter-spacing: 2px;\\r\\n    text-transform: uppercase;\\r\\n}\\r\\n\\r\\n.fh-process h2 {\\r\\n    margin: 0 0 16px;\\r\\n    color: #173d5b;\\r\\n    font-size: 38px;\\r\\n    font-weight: 300;\\r\\n    line-height: 1.25;\\r\\n}\\r\\n\\r\\n.fh-process-intro {\\r\\n    margin: 0;\\r\\n    color: #5f6973;\\r\\n    font-size: 17px;\\r\\n    line-height: 1.8;\\r\\n}\\r\\n\\r\\n.fh-process-grid {\\r\\n    display: grid;\\r\\n    grid-template-columns: repeat(4, 1fr);\\r\\n    gap: 22px;\\r\\n}\\r\\n\\r\\n.fh-step {\\r\\n    position: relative;\\r\\n    padding: 38px 26px 34px;\\r\\n    background: #ffffff;\\r\\n    border: 1px solid #e2ebf2;\\r\\n    border-radius: 18px;\\r\\n    box-shadow: 0 12px 30px rgba(18, 79, 124, 0.08);\\r\\n    transition: transform 0.25s ease, box-shadow 0.25s ease;\\r\\n}\\r\\n\\r\\n.fh-step:hover {\\r\\n    transform: translateY(-5px);\\r\\n    box-shadow: 0 18px 38px rgba(18, 79, 124, 0.13);\\r\\n}\\r\\n\\r\\n.fh-step-number {\\r\\n    position: absolute;\\r\\n    top: 16px;\\r\\n    right: 18px;\\r\\n    color: #aac8dc;\\r\\n    font-size: 14px;\\r\\n    font-weight: 700;\\r\\n    letter-spacing: 1px;\\r\\n}\\r\\n\\r\\n.fh-step-icon {\\r\\n    width: 66px;\\r\\n    height: 66px;\\r\\n    margin: 0 auto 24px;\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    justify-content: center;\\r\\n    background: #eef7fd;\\r\\n    border-radius: 50%;\\r\\n    color: #124f7c;\\r\\n}\\r\\n\\r\\n.fh-step-icon svg {\\r\\n    width: 31px;\\r\\n    height: 31px;\\r\\n    display: block;\\r\\n    stroke: currentColor;\\r\\n}\\r\\n\\r\\n.fh-step h3 {\\r\\n    margin: 0 0 16px;\\r\\n    color: #124f7c;\\r\\n    font-size: 22px;\\r\\n    font-weight: 500;\\r\\n    line-height: 1.35;\\r\\n}\\r\\n\\r\\n.fh-step p {\\r\\n    margin: 0;\\r\\n    color: #5d6872;\\r\\n    font-size: 16px;\\r\\n    line-height: 1.75;\\r\\n}\\r\\n\\r\\n.fh-process-button-wrap {\\r\\n    margin-top: 38px;\\r\\n}\\r\\n\\r\\n.fh-process-button {\\r\\n    display: inline-block;\\r\\n    padding: 14px 28px;\\r\\n    background: #124f7c;\\r\\n    color: #ffffff;\\r\\n    border: 2px solid #124f7c;\\r\\n    border-radius: 7px;\\r\\n    text-decoration: none;\\r\\n    font-size: 15px;\\r\\n    font-weight: 600;\\r\\n    line-height: 1.3;\\r\\n    transition: background 0.2s ease, color 0.2s ease;\\r\\n}\\r\\n\\r\\n.fh-process-button:hover {\\r\\n    background: #ffffff;\\r\\n    color: #124f7c;\\r\\n}\\r\\n\\r\\n@media (max-width: 1000px) {\\r\\n    .fh-process-grid {\\r\\n        grid-template-columns: repeat(2, 1fr);\\r\\n    }\\r\\n}\\r\\n\\r\\n@media (max-width: 650px) {\\r\\n    .fh-process {\\r\\n        margin: 55px auto;\\r\\n        padding: 0 16px;\\r\\n    }\\r\\n\\r\\n    .fh-process h2 {\\r\\n        font-size: 31px;\\r\\n    }\\r\\n\\r\\n    .fh-process-intro {\\r\\n        font-size: 16px;\\r\\n    }\\r\\n\\r\\n    .fh-process-grid {\\r\\n        grid-template-columns: 1fr;\\r\\n    }\\r\\n\\r\\n    .fh-step {\\r\\n        padding: 34px 25px 30px;\\r\\n    }\\r\\n}\\r\\n\\u003c/style\\u003e\\r\\n\\r\\n\\u003csection class=\\u0022fh-process\\u0022\\u003e\\r\\n\\r\\n    \\u003cdiv class=\\u0022fh-process-heading\\u0022\\u003e\\r\\n\\r\\n        \\u003cp class=\\u0022fh-process-label\\u0022\\u003e\\r\\n            Simple Booking Process\\r\\n        \\u003c/p\\u003e\\r\\n\\r\\n        \\u003ch2\\u003e\\r\\n            How Do I Book a Private Flight?\\r\\n        \\u003c/h2\\u003e\\r\\n\\r\\n        \\u003cp class=\\u0022fh-process-intro\\u0022\\u003e\\r\\n            Booking your private flight is simple. From your first request to takeoff, our team guides you through every step for a smooth and stress-free journey.\\r\\n        \\u003c/p\\u003e\\r\\n\\r\\n    \\u003c/div\\u003e\\r\\n\\r\\n    \\u003cdiv class=\\u0022fh-process-grid\\u0022\\u003e\\r\\n\\r\\n        \\u003c!\\u002d\\u002d STEP 1 \\u002d\\u002d\\u003e\\r\\n        \\u003cdiv class=\\u0022fh-step\\u0022\\u003e\\r\\n\\r\\n            \\u003cspan class=\\u0022fh-step-number\\u0022\\u003e01\\u003c/span\\u003e\\r\\n\\r\\n            \\u003cdiv class=\\u0022fh-step-icon\\u0022 aria-hidden=\\u0022true\\u0022\\u003e\\r\\n                \\u003csvg viewBox=\\u00220 0 24 24\\u0022 fill=\\u0022none\\u0022 stroke-width=\\u00221.7\\u0022 stroke-linecap=\\u0022round\\u0022 stroke-linejoin=\\u0022round\\u0022\\u003e\\r\\n                    \\u003crect x=\\u00223\\u0022 y=\\u00225\\u0022 width=\\u002218\\u0022 height=\\u002216\\u0022 rx=\\u00222\\u0022\\u003e\\u003c/rect\\u003e\\r\\n                    \\u003cpath d=\\u0022M16 3v4M8 3v4M3 10h18\\u0022\\u003e\\u003c/path\\u003e\\r\\n                    \\u003cpath d=\\u0022M8 14h3M13 14h3M8 17h3\\u0022\\u003e\\u003c/path\\u003e\\r\\n                \\u003c/svg\\u003e\\r\\n            \\u003c/div\\u003e\\r\\n\\r\\n            \\u003ch3\\u003e\\r\\n                Request Your Flight\\r\\n            \\u003c/h3\\u003e\\r\\n\\r\\n            \\u003cp\\u003e\\r\\n                Choose your route, travel date and number of passengers using our online booking form.\\r\\n            \\u003c/p\\u003e\\r\\n\\r\\n        \\u003c/div\\u003e\\r\\n\\r\\n\\r\\n        \\u003c!\\u002d\\u002d STEP 2 \\u002d\\u002d\\u003e\\r\\n        \\u003cdiv class=\\u0022fh-step\\u0022\\u003e\\r\\n\\r\\n            \\u003cspan class=\\u0022fh-step-number\\u0022\\u003e02\\u003c/span\\u003e\\r\\n\\r\\n            \\u003cdiv class=\\u0022fh-step-icon\\u0022 aria-hidden=\\u0022true\\u0022\\u003e\\r\\n                \\u003csvg viewBox=\\u00220 0 24 24\\u0022 fill=\\u0022none\\u0022 stroke-width=\\u00221.7\\u0022 stroke-linecap=\\u0022round\\u0022 stroke-linejoin=\\u0022round\\u0022\\u003e\\r\\n                    \\u003cpath d=\\u0022M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4z\\u0022\\u003e\\u003c/path\\u003e\\r\\n                    \\u003cpath d=\\u0022M8 9h8M8 13h5\\u0022\\u003e\\u003c/path\\u003e\\r\\n                \\u003c/svg\\u003e\\r\\n            \\u003c/div\\u003e\\r\\n\\r\\n            \\u003ch3\\u003e\\r\\n                Receive Your Quote\\r\\n            \\u003c/h3\\u003e\\r\\n\\r\\n            \\u003cp\\u003e\\r\\n                We confirm availability, answer your questions and send you a personalized flight quotation.\\r\\n            \\u003c/p\\u003e\\r\\n\\r\\n        \\u003c/div\\u003e\\r\\n\\r\\n\\r\\n        \\u003c!\\u002d\\u002d STEP 3 \\u002d\\u002d\\u003e\\r\\n        \\u003cdiv class=\\u0022fh-step\\u0022\\u003e\\r\\n\\r\\n            \\u003cspan class=\\u0022fh-step-number\\u0022\\u003e03\\u003c/span\\u003e\\r\\n\\r\\n            \\u003cdiv class=\\u0022fh-step-icon\\u0022 aria-hidden=\\u0022true\\u0022\\u003e\\r\\n                \\u003csvg viewBox=\\u00220 0 24 24\\u0022 fill=\\u0022none\\u0022 stroke-width=\\u00221.7\\u0022 stroke-linecap=\\u0022round\\u0022 stroke-linejoin=\\u0022round\\u0022\\u003e\\r\\n                    \\u003cpath d=\\u0022M9 11l3 3L22 4\\u0022\\u003e\\u003c/path\\u003e\\r\\n                    \\u003cpath d=\\u0022M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\\u0022\\u003e\\u003c/path\\u003e\\r\\n                \\u003c/svg\\u003e\\r\\n            \\u003c/div\\u003e\\r\\n\\r\\n            \\u003ch3\\u003e\\r\\n                Confirm Your Booking\\r\\n            \\u003c/h3\\u003e\\r\\n\\r\\n            \\u003cp\\u003e\\r\\n                Secure your reservation with a deposit and receive your confirmation and departure details.\\r\\n            \\u003c/p\\u003e\\r\\n\\r\\n        \\u003c/div\\u003e\\r\\n\\r\\n\\r\\n        \\u003c!\\u002d\\u002d STEP 4 \\u002d\\u002d\\u003e\\r\\n        \\u003cdiv class=\\u0022fh-step\\u0022\\u003e\\r\\n\\r\\n            \\u003cspan class=\\u0022fh-step-number\\u0022\\u003e04\\u003c/span\\u003e\\r\\n\\r\\n            \\u003cdiv class=\\u0022fh-step-icon\\u0022 aria-hidden=\\u0022true\\u0022\\u003e\\r\\n                \\u003csvg viewBox=\\u00220 0 24 24\\u0022 fill=\\u0022none\\u0022 stroke-width=\\u00221.7\\u0022 stroke-linecap=\\u0022round\\u0022 stroke-linejoin=\\u0022round\\u0022\\u003e\\r\\n                    \\u003cpath d=\\u0022M22 2L11 13\\u0022\\u003e\\u003c/path\\u003e\\r\\n                    \\u003cpath d=\\u0022M22 2l-7 20-4-9-9-4z\\u0022\\u003e\\u003c/path\\u003e\\r\\n                \\u003c/svg\\u003e\\r\\n            \\u003c/div\\u003e\\r\\n\\r\\n            \\u003ch3\\u003e\\r\\n                Enjoy Your Flight\\r\\n            \\u003c/h3\\u003e\\r\\n\\r\\n            \\u003cp\\u003e\\r\\n                Meet your pilot, board your aircraft and enjoy spectacular aerial views on the way to your destination.\\r\\n            \\u003c/p\\u003e\\r\\n\\r\\n        \\u003c/div\\u003e\\r\\n\\r\\n    \\u003c/div\\u003e\\r\\n\\r\\n    \\u003cdiv class=\\u0022fh-process-button-wrap\\u0022\\u003e\\r\\n        \\u003ca href=\\u0022YOUR-BOOKING-PAGE-URL\\u0022 class=\\u0022fh-process-button\\u0022\\u003e\\r\\n            Request Your Flight\\r\\n        \\u003c/a\\u003e\\r\\n    \\u003c/div\\u003e\\r\\n\\r\\n\\u003c/section\\u003e\",\"