INSERT INTO `wp_termmeta` VALUES (95,9,'plane_info','Our Cessna 206/207 can accommodate up to 5 passengers in your private group.\r\nPrice is always for the private hired aircraft, not per person.\r\n\r\nLuggage Allowance\r\n\r\n1–2 Passengers\r\n\r\nUp to 20 kg (44 lbs) of luggage per person\r\nChecked luggage and carry-on permitted (subject to aircraft weight limits 330kg between all passengers and luggage) \r\n\r\n 3–5 Passengers\r\n\r\nOne carry-on bag only\r\nMaximum 10 kg (22 lbs) per person\r\nNo large checked luggage possible\r\n\r\nNeed more luggage?\r\nWe can arrange a land luggage transfer or a second aircraft for an additional fee.\r\n\r\nIf your group\'s luggage exceeds the permitted allowance, you have two options:\r\n\r\nBook a second aircraft to accommodate the additional luggage (additional flight charges apply), or use our luggage transfer service. We can transport your excess luggage by land directly to or from your hotel for USD 350.');
INSERT INTO `wp_termmeta` VALUES (96,9,'_plane_info','field_6a5637a4d383d');
INSERT INTO `wp_termmeta` VALUES (97,10,'plane_info','Our Cessna 206/207 can accommodate up to 5 passengers in your private group.\r\nPrice is always for the private hired aircraft, not per person.\r\n\r\nLuggage Allowance\r\n\r\n1–2 Passengers\r\n\r\nUp to 20 kg (44 lbs) of luggage per person\r\nChecked luggage and carry-on permitted (subject to aircraft weight limits 330kg between all passengers and luggage) \r\n\r\n 3–5 Passengers\r\n\r\nOne carry-on bag only\r\nMaximum 10 kg (22 lbs) per person\r\nNo large checked luggage possible\r\n\r\nNeed more luggage?\r\nWe can arrange a land luggage transfer or a second aircraft for an additional fee.\r\n\r\nIf your group\'s luggage exceeds the permitted allowance, you have two options:\r\n\r\nBook a second aircraft to accommodate the additional luggage (additional flight charges apply), or use our luggage transfer service. We can transport your excess luggage by land directly to or from your hotel for USD 350.');
INSERT INTO `wp_termmeta` VALUES (98,10,'_plane_info','field_6a5637a4d383d');
INSERT INTO `wp_termmeta` VALUES (99,41,'plane_info','if you group is larger then 5 people you can rent multiple planes at the same time. There is no larger aircraft flying to Holbox at the moment.');
